<?php if (!isset($categories,$recipients)) exit; ?>
<label>Judul dokumen<input name="nama" maxlength="255" required value="<?= h($name) ?>" placeholder="Misalnya, bukti pembayaran pajak kendaraan"></label>
<div class="fields"><label>Kategori<select name="kategori" required><option value="">Pilih kategori</option><?php foreach ($categories as $k): ?><option value="<?= $k['kategori_id'] ?>" <?= $category == $k['kategori_id']?'selected':'' ?>><?= h($k['kategori_nama']) ?></option><?php endforeach; ?></select></label>
<label>Akses dokumen<select name="penerima" required><option value="">Pilih penerima</option><option value="shared" <?= $recipient === 'shared'?'selected':'' ?>>Semua pengguna terdaftar</option><?php foreach ($recipients as $u): ?><option value="<?= $u['user_id'] ?>" <?= $recipient == $u['user_id']?'selected':'' ?>><?= h($u['user_nama'] . ' (@' . $u['user_username'] . ')') ?></option><?php endforeach; ?></select></label></div>
<label>Keterangan <small>(opsional)</small><textarea name="keterangan" rows="3"><?= h($notes) ?></textarea></label>
